170:/**
171: * Smooth cloudy noise in 0..1 (mean 0.5) with features about `size` meters across: three octaves of gradient noise.
172: * The same `seed` gives the same field everywhere, so neighbouring parts continue it.
173: */
174:export function noise(p: Vector3, size: number, seed = 0) {
175:  let sum = 0;
176:  let amp = 1;
177:  let f = 1 / size;
178:  for (let o = 0; o < 3; o++) {
179:    sum += amp * perlin(p.x * f + o * 17.1, p.y * f + o * 31.7, p.z * f + o * 11.3, seed + o * 101);
180:    amp *= 0.5;
181:    f *= 2;
182:  }
183:  return Math.min(Math.max(0.5 + sum * 0.55, 0), 1);
